import { cwd as getCwd, env as getProcessEnv, setEnv } from "../../platform/compat/process.js";
import { load as loadDotenv } from "../../platform/compat/std/dotenv.js";
import { markEnvFileValue } from "../../platform/compat/process/env.js";
const DEFAULT_AGENT_SERVICE_ENV_FILES = [".env", ".env.local"];
function joinEnvPath(cwd, file) {
    if (file.startsWith("/") || file.startsWith("./") || file.startsWith("../")) {
        return file;
    }
    return `${cwd.replace(/\/$/, "")}/${file}`;
}
/** Loads agent service env files. */
export async function loadAgentServiceEnvFiles(options = {}) {
    const cwd = options.cwd ?? getCwd();
    const files = options.files ?? DEFAULT_AGENT_SERVICE_ENV_FILES;
    const protectedKeys = new Set(Object.keys(getProcessEnv()));
    const loadedFiles = [];
    let loadedVariables = 0;
    for (const file of files) {
        const envPath = joinEnvPath(cwd, file);
        const parsed = await loadDotenv({ envPath, allowEmptyValues: true });
        const entries = Object.entries(parsed);
        if (entries.length === 0) {
            continue;
        }
        loadedFiles.push(envPath);
        for (const [key, value] of entries) {
            if (protectedKeys.has(key)) {
                continue;
            }
            setEnv(key, value);
            markEnvFileValue(key);
            loadedVariables++;
        }
    }
    return { loadedFiles, loadedVariables };
}
/** Loads hosted agent service env files. */
export const loadHostedAgentServiceEnvFiles = loadAgentServiceEnvFiles;
